"""Unit tests for the vehicle classification dataset loader."""

import unittest
import os

try:
    import tensorflow as tf
    # vehicle_dataset imports TensorFlow unguarded, so a TF/protobuf conflict
    # surfaces here too — keep it inside the guard so the suite skips cleanly
    # when TF is unavailable (TF is training-only; runtime uses PaddleOCR).
    from src.datasets.vehicle_dataset import load_classification_dataset
    TF_AVAILABLE = True
except ImportError:
    TF_AVAILABLE = False

# Path to mock car brand images generated by mock_generator.py
DATA_DIR = os.path.join("main", "data", "raw", "car_brands")

# Expected values from config.yaml / mock_generator.py
BATCH_SIZE = 32
IMG_HEIGHT = 224
IMG_WIDTH = 224
NUM_CLASSES = 8  # Toyota, Hyundai, Kia, Mazda, Honda, VinFast, Ford, Mitsubishi


@unittest.skipIf(not TF_AVAILABLE, "TensorFlow not installed — skipping dataset tests")
class TestVehicleDataset(unittest.TestCase):
    """Tests for load_classification_dataset with mock car brand images."""

    @classmethod
    def setUpClass(cls):
        """Load the dataset once and cache for all tests.

        Raises:
            unittest.SkipTest: If mock data directory is missing.
        """
        if not os.path.exists(DATA_DIR):
            raise unittest.SkipTest(
                f"Mock data not found at {DATA_DIR}. "
                "Run mock_generator.py first."
            )

        cls.train_ds, cls.val_ds = load_classification_dataset(
            data_dir=DATA_DIR,
            batch_size=BATCH_SIZE,
            img_height=IMG_HEIGHT,
            img_width=IMG_WIDTH,
        )

        # Grab one batch for shape / value tests
        cls.sample_images, cls.sample_labels = next(iter(cls.train_ds))

    def test_dataset_loads_without_error(self):
        """Verify load_classification_dataset returns without exceptions."""
        self.assertIsNotNone(self.train_ds)
        self.assertIsNotNone(self.val_ds)

    def test_dataset_returns_tuple(self):
        """Verify the loader returns a (train_ds, val_ds) tuple."""
        self.assertIsInstance(self.train_ds, tf.data.Dataset)
        self.assertIsInstance(self.val_ds, tf.data.Dataset)

    def test_image_shape(self):
        """Verify image tensors have shape (batch, 224, 224, 3)."""
        shape = self.sample_images.shape
        self.assertEqual(len(shape), 4)
        # batch dim may be smaller than BATCH_SIZE for tiny datasets
        self.assertLessEqual(shape[0], BATCH_SIZE)
        self.assertEqual(shape[1], IMG_HEIGHT)
        self.assertEqual(shape[2], IMG_WIDTH)
        self.assertEqual(shape[3], 3)

    def test_labels_are_categorical(self):
        """Verify label tensors have shape (batch, NUM_CLASSES)."""
        shape = self.sample_labels.shape
        self.assertEqual(len(shape), 2)
        self.assertEqual(shape[1], NUM_CLASSES)

    def test_pixel_values_normalized(self):
        """Verify all pixel values fall within [0.0, 1.0]."""
        min_val = float(tf.reduce_min(self.sample_images))
        max_val = float(tf.reduce_max(self.sample_images))
        self.assertGreaterEqual(min_val, 0.0)
        self.assertLessEqual(max_val, 1.0)


@unittest.skipIf(not TF_AVAILABLE, "TensorFlow not installed — skipping dataset tests")
class TestLoadSplitDatasetTaskParam(unittest.TestCase):
    """Tests for load_split_dataset with the new ``task`` parameter."""

    def test_load_split_accepts_task(self):
        """load_split_dataset with task='brand' returns correctly shaped batches."""
        import tempfile
        import numpy as np
        from PIL import Image
        from src.datasets.vehicle_dataset import load_split_dataset

        with tempfile.TemporaryDirectory() as tmp:
            # Create minimal train/val/test structure: 2 classes, 1 image each
            for split in ("train", "val", "test"):
                for cls in ("a", "b"):
                    d = os.path.join(tmp, split, cls)
                    os.makedirs(d, exist_ok=True)
                    Image.fromarray(
                        np.zeros((8, 8, 3), dtype=np.uint8)
                    ).save(os.path.join(d, "x.jpg"))

            tr, _val, _test, names = load_split_dataset(
                tmp, batch_size=2, img_height=8, img_width=8, task="brand"
            )
            x, _y = next(iter(tr))
            self.assertLessEqual(float(tf.reduce_max(x)), 1.0 + 1e-3,
                                 "Pixel values should be normalised to [0,1]")
            self.assertEqual(names, ["a", "b"])

    def test_load_split_color_task_no_hue(self):
        """load_split_dataset with task='color' completes without error."""
        import tempfile
        import numpy as np
        from PIL import Image
        from src.datasets.vehicle_dataset import load_split_dataset

        with tempfile.TemporaryDirectory() as tmp:
            for split in ("train", "val", "test"):
                for cls in ("red", "blue"):
                    d = os.path.join(tmp, split, cls)
                    os.makedirs(d, exist_ok=True)
                    Image.fromarray(
                        np.zeros((8, 8, 3), dtype=np.uint8)
                    ).save(os.path.join(d, "x.jpg"))

            tr, _val, _test, names = load_split_dataset(
                tmp, batch_size=2, img_height=8, img_width=8, task="color"
            )
            x, _y = next(iter(tr))
            self.assertLessEqual(float(tf.reduce_max(x)), 1.0 + 1e-3,
                                 "Pixel values should be normalised to [0,1]")
            self.assertEqual(sorted(names), ["blue", "red"])


if __name__ == "__main__":
    unittest.main()
